  FROM () x

	AND x.APPLCNT_ID = #{scopeApplcntId}
	AND x.ORGNZT_ID = #{scopeOrgnztId}

		AND x.STTUS = 'PENDING'
		AND (x.HEAD_APRV_ID = #{scopeInboxUserId}

		     OR (x.HEAD_APRV_ID IS NULL AND (x.APPLCNT_ID <> #{scopeInboxUserId} OR NOT ))

		)

	AND x.STTUS = #{searchSttus}
	AND x.REQ_NO LIKE CONCAT('%', #{searchReqNo}, '%')

