UPDATE ASSET_REQ_LINE
   SET LINE_STTUS = #{lineSttus}
     , APRV_QTY = #{aprvQty}
     , REJECT_RESN = #{rejectResn}
 WHERE REQ_NO = #{reqNo}
   AND ITEM_CODE = #{itemCode}

UPDATE ASSET_REQ
   SET STTUS = #{sttus}

     , APRV_ID = #{actorId}
     , APRV_PNTTM = SYSDATE()

     , LAST_PROCESS_ID = #{actorId}
     , LAST_PROCESS_PNTTM = SYSDATE()
 WHERE REQ_NO = #{reqNo}
